  role: 'thinking';
  content: string;
  /** When the entry was created, ISO 8601: `2026-01-15T14:30:00.000Z` or `2026-01-15T15:30:00.000+01:00` alike, so parse before comparing; absent on an entry stored before 0.9. */
  timestamp?: string;
